import React, { useState, useEffect } from 'react';
import axios from 'axios';

function App() {
  const [atividades, setAtividades] = useState([]);
  const [paginaAtual, setPaginaAtual] = useState(1);
  const [usuarioLogado, setUsuarioLogado] = useState(null);
  const [mostrarModal, setMostrarModal] = useState(false);
  const [email, setEmail] = useState('');
  const [senha, setSenha] = useState('');

  const ITENS_POR_PAGINA = 4;

  // Buscar atividades do Backend
  useEffect(() => {
    carregarAtividades();
  }, []);

  const carregarAtividades = async () => {
    try {
      const response = await axios.get('http://localhost:3000/atividades');
      setAtividades(response.data);
    } catch (err) {
      console.error('Erro ao buscar atividades:', err);
    }
  };

  // Regras de Conversão
  const formatarDistancia = (metros) => (metros / 1000).toFixed(1) + ' km';
  const formatarDuracao = (minutos) => (minutos / 60).toFixed(1) + ' h';

  // Lógica de Bloqueio sem Login
  const executarAcaoComAutenticacao = (acao) => {
    if (!usuarioLogado) {
      setMostrarModal(true);
    } else {
      acao();
    }
  };

  const handleCurtir = (id) => {
    executarAcaoComAutenticacao(() => {
      setAtividades(atividades.map(item => 
        item.id === id ? { ...item, curtidas_count: item.curtidas_count + 1 } : item
      ));
    });
  };

  const handleLogin = (e) => {
    e.preventDefault();
    if (email && senha) {
      setUsuarioLogado({ email });
      setMostrarModal(false);
    }
  };

  // Lógica de Paginação (Máximo 4 por página)
  const indiceUltimoItem = paginaAtual * ITENS_POR_PAGINA;
  const indicePrimeiroItem = indiceUltimoItem - ITENS_POR_PAGINA;
  const atividadesPaginadas = atividades.slice(indicePrimeiroItem, indiceUltimoItem);
  const totalPaginas = Math.ceil(atividades.length / ITENS_POR_PAGINA);

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'Arial, sans-serif' }}>
      <header style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
        <h1>SAEP Saúde - Feed</h1>
        {usuarioLogado ? (
          <span>Bem-vindo, {usuarioLogado.email}</span>
        ) : (
          <button onClick={() => setMostrarModal(true)}>Entrar</button>
        )}
      </header>

      {/* Listagem de Cards */}
      <div style={{ display: 'grid', gap: '15px' }}>
        {atividadesPaginadas.map((item) => (
          <div key={item.id} style={{ border: '1px solid #ccc', borderRadius: '8px', padding: '15px', background: '#f9f9f9' }}>
            <h3>{item.tipo}</h3>
            <p><strong>Distância:</strong> {formatarDistancia(item.distancia_m)}</p>
            <p><strong>Duração:</strong> {formatarDuracao(item.duracao_min)}</p>
            <button onClick={() => handleCurtir(item.id)}>
              ❤️ Curtir ({item.curtidas_count})
            </button>
          </div>
        ))}
      </div>

      {/* Controles de Paginação */}
      {totalPaginas > 1 && (
        <div style={{ marginTop: '20px', display: 'flex', gap: '10px', justifyContent: 'center' }}>
          <button disabled={paginaAtual === 1} onClick={() => setPaginaAtual(prev => prev - 1)}>
            Anterior
          </button>
          <span>Página {paginaAtual} de {totalPaginas}</span>
          <button disabled={paginaAtual === totalPaginas} onClick={() => setPaginaAtual(prev => prev + 1)}>
            Próxima
          </button>
        </div>
      )}

      {/* Modal de Login */}
      {mostrarModal && (
        <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', background: 'rgba(0,0,0,0.5)', display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
          <div style={{ background: '#fff', padding: '20px', borderRadius: '8px', width: '300px' }}>
            <h2>Login Necessário</h2>
            <form onSubmit={handleLogin}>
              <input type="email" placeholder="E-mail" value={email} onChange={e => setEmail(e.target.value)} required style={{ width: '100%', marginBottom: '10px' }} />
              <input type="password" placeholder="Senha" value={senha} onChange={e => setSenha(e.target.value)} required style={{ width: '100%', marginBottom: '10px' }} />
              <button type="submit" style={{ width: '100%', marginBottom: '10px' }}>Entrar</button>
            </form>
            <button onClick={() => setMostrarModal(false)} style={{ width: '100%' }}>Cancelar</button>
          </div>
        </div>
      )}
    </div>
  );
}

export default App;
